1	/**
2	 * https://gist.github.com/DLiblik/96801665f9b6c935f12c1071d37eae95
3	 Compares two items (values or references) for nested equivalency, meaning that
4	 at root and at each key or index they are equivalent as follows:
5	 - If a value type, values are either hard equal (===) or are both NaN
6	     (different than JS where NaN !== NaN)
7	 - If functions, they are the same function instance or have the same value
8	     when converted to string via `toString()`
9	 - If Date objects, both have the same getTime() or are both NaN (invalid)
10	 - If arrays, both are same length, and all contained values areEquivalent
11	     recursively - only contents by numeric key are checked
12	 - If other object types, enumerable keys are the same (the keys themselves)
13	     and values at every key areEquivalent recursively
14	 Author: Dathan Liblik
15	 License: Free to use anywhere by anyone, as-is, no guarantees of any kind.
16	 @param value1 First item to compare
17	 @param value2 Other item to compare
18	 @param stack Used internally to track circular refs - don't set it
19	 */
20	module.exports = function areEquivalent(value1, value2, numToString = false, stack = []) {
21	  if (numToString) {
22	    if (value1 !== null && !isNaN(value1)) value1 = String(value1)
23	    if (value2 !== null && !isNaN(value2)) value2 = String(value2)
24	  }
25	
26	  // Numbers, strings, null, undefined, symbols, functions, booleans.
27	  // Also: objects (incl. arrays) that are actually the same instance
28	  if (value1 === value2) {
29	    // Fast and done
30	    return true
31	  }
32	
33	  // Truthy check to handle value1=null, value2=Object
34	  if ((value1 && !value2) || (!value1 && value2)) {
35	    // console.log('value1/value2 falsy mismatch', value1, value2)
36	    return false
37	  }
38	
39	  const type1 = typeof value1
40	
41	  // Ensure types match
42	  if (type1 !== typeof value2) {
43	    // console.log('type diff', type1, typeof value2)
44	    return false
45	  }
46	
47	  // Special case for number: check for NaN on both sides
48	  // (only way they can still be equivalent but not equal)
49	  if (type1 === 'number') {
50	    // Failed initial equals test, but could still both be NaN
51	    return (isNaN(value1) && isNaN(value2));
52	  }
53	
54	  // Special case for function: check for toString() equivalence
55	  if (type1 === 'function') {
56	    // Failed initial equals test, but could still have equivalent
57	    // implementations - note, will match on functions that have same name
58	    // and are native code: `function abc() { [native code] }`
59	    return value1.toString() === value2.toString()
60	  }
61	
62	  // For these types, cannot still be equal at this point, so fast-fail
63	  if (type1 === 'bigint' || type1 === 'boolean' ||
64	    type1 === 'function' || type1 === 'string' ||
65	    type1 === 'symbol') {
